#include "provider.h"
#include <filesystem>
#include <fstream>
#include <thread>
#include <memory>
#include <mutex>
namespace fs=std::filesystem;
static std::vector<std::string> snapshot(API&a){std::vector<std::string>v;v.push_back("regs:"+std::to_string(a.ggml_backend_reg_count()));for(size_t i=0;i<a.ggml_backend_reg_count();i++)v.push_back("reg:"+std::string(a.ggml_backend_reg_name(a.ggml_backend_reg_get(i))));v.push_back("devs:"+std::to_string(a.ggml_backend_dev_count()));for(size_t i=0;i<a.ggml_backend_dev_count();i++){auto*d=a.ggml_backend_dev_get(i);v.push_back("dev:"+std::string(a.ggml_backend_dev_name(d))+":"+std::to_string(a.ggml_backend_dev_type(d)));}return v;}
static void empty(API&a){while(a.ggml_backend_reg_count())a.ggml_backend_unload(a.ggml_backend_reg_get(0));req(a.ggml_backend_dev_count()==0,"no stale registered devices");}
struct Result{std::vector<std::string>state,events;};
static Result registry(API&a){Result o;req(!a.ggml_backend_reg_count()&&!a.ggml_backend_dev_count(),"isolated empty registry");a.ggml_backend_register(nullptr);std::vector<std::unique_ptr<Provider>>f;for(int i=0;i<48;i++){f.emplace_back(new Provider(a,o.events,("Backend"+std::to_string(i)).c_str()));f.back()->cpu=i%3==0;f.back()->device.iface.init_backend=[](ggml_backend_dev_t d,const char*p){auto*x=(Provider*)d->context;x->log.push_back("init:"+x->id+":"+(p?p:"NULL"));return &x->backend;};f.back()->reg.iface.get_device_count=[](ggml_backend_reg_t r){auto*x=(Provider*)r->context;x->log.push_back("count:"+x->id);req(x->a.ggml_backend_reg_by_name(x->id.c_str())==r,"registry visible during reentrant count callback");return size_t(2);};f.back()->reg.iface.get_device=[](ggml_backend_reg_t r,size_t i){auto*x=(Provider*)r->context;x->log.push_back("get:"+x->id+":"+std::to_string(i));return i<2?&x->device:nullptr;};a.ggml_backend_register(&f.back()->reg);a.ggml_backend_register(&f.back()->reg);a.ggml_backend_device_register(&f.back()->device);}req(a.ggml_backend_reg_count()==48&&a.ggml_backend_dev_count()==48,"registration and device dedup");for(int i=0;i<48;i++){auto name="bACKEND"+std::to_string(i);req(a.ggml_backend_reg_get(i)==&f[i]->reg&&a.ggml_backend_dev_get(i)==&f[i]->device,"insertion order and pointer identity");req(a.ggml_backend_reg_by_name(name.c_str())==&f[i]->reg&&a.ggml_backend_dev_by_name(name.c_str())==&f[i]->device,"case-insensitive lookup");req(a.ggml_backend_init_by_name(name.c_str(),"params")==&f[i]->backend,"init by name and params");}req(!a.ggml_backend_reg_by_name("unknown")&&!a.ggml_backend_dev_by_name("unknown")&&!a.ggml_backend_init_by_name("unknown",nullptr),"absent lookups");req(a.ggml_backend_dev_by_type(GGML_BACKEND_DEVICE_TYPE_CPU)==&f[0]->device&&a.ggml_backend_dev_by_type(GGML_BACKEND_DEVICE_TYPE_GPU)==&f[1]->device,"first device type priority");req(a.ggml_backend_init_best()==&f[1]->backend&&a.ggml_backend_init_by_type(GGML_BACKEND_DEVICE_TYPE_CPU,"params")==&f[0]->backend,"best backend priority");o.state=snapshot(a);for(int i=0;i<48;i+=2)a.ggml_backend_unload(&f[i]->reg);auto p=snapshot(a);o.state.insert(o.state.end(),p.begin(),p.end());a.ggml_backend_unload(&f[0]->reg);a.ggml_backend_register(&f[0]->reg);req(a.ggml_backend_reg_get(24)==&f[0]->reg,"re-register appends");empty(a);req(!a.ggml_backend_init_best(),"empty init best");return o;}
static std::vector<std::string> lines(const fs::path&p){std::ifstream f(p);std::vector<std::string>v;std::string s;while(std::getline(f,s))v.push_back(s);return v;}
static Result dynamic(API&a,const fs::path&plugins,const fs::path&events){Result out;std::ofstream(events).close();for(auto name:{"zero","low","high","negative","base","missing","null","abi"}){auto path=plugins/(std::string(name)+".so");auto*r=a.ggml_backend_load(path.c_str());bool good=std::strcmp(name,"zero")&&std::strcmp(name,"missing")&&std::strcmp(name,"null")&&std::strcmp(name,"abi");req((r!=nullptr)==good,"plugin validity/score/API");if(good){req(a.ggml_backend_reg_count()==1&&a.ggml_backend_dev_count()==1,"plugin device publication");req(std::strcmp(a.ggml_backend_reg_name(r),name)==0,"plugin identity");auto*again=a.ggml_backend_load(path.c_str());req(again==r&&a.ggml_backend_reg_count()==1,"duplicate plugin reference not republished");out.state.push_back(name);a.ggml_backend_unload(r);req(!a.ggml_backend_reg_count()&&!a.ggml_backend_dev_count(),"plugin explicit unload removes devices");}else req(!a.ggml_backend_reg_count(),"invalid plugin cannot publish");}req(!a.ggml_backend_load((plugins/"absent.so").c_str()),"missing shared library");out.events=lines(events);return out;}
static Result best(API&a,const fs::path&plugins,const fs::path&events){Result out;std::ofstream(events).close();auto query=sym<ggml_backend_reg_t(*)(const char*,bool,const char*)>(a.h,"fg165_probe_best");auto dir=plugins/"best";auto*r=query("test",true,dir.c_str());req(r&&std::strcmp(a.ggml_backend_reg_name(r),"high")==0,"highest score chosen");out.state=snapshot(a);empty(a);r=query("base",false,(plugins/"fallback").c_str());req(r&&std::strcmp(a.ggml_backend_reg_name(r),"base")==0,"base fallback accepts missing score");empty(a);req(!query("missing",false,dir.c_str()),"missing variant and base");req(!query("does-not-exist-165",true,nullptr),"default executable/cwd search");a.ggml_backend_load_all_from_path((plugins/"all").c_str());req(a.ggml_backend_reg_count()==2,"load all cuda/cpu count");req(std::strcmp(a.ggml_backend_reg_name(a.ggml_backend_reg_get(0)),"high")==0&&std::strcmp(a.ggml_backend_reg_name(a.ggml_backend_reg_get(1)),"base")==0,"load all fixed cuda/cpu order");auto s=snapshot(a);out.state.insert(out.state.end(),s.begin(),s.end());empty(a);out.events=lines(events);return out;}
static void compare(const Result&a,const Result&b){if(a.events!=b.events){for(size_t i=0;i<a.events.size()||i<b.events.size();i++){auto x=i<a.events.size()?a.events[i]:"<end>",y=i<b.events.size()?b.events[i]:"<end>";if(x!=y){fprintf(stderr,"event %zu native=%s goose=%s\n",i,x.c_str(),y.c_str());break;}}}req(a.state==b.state,"registry states exact");req(a.events==b.events,"plugin and init event order exact");event_records+=a.events.size();}
static void concurrent(API&a){phase="concurrent registry";std::vector<std::string>log;std::vector<std::unique_ptr<Provider>>providers;for(int i=0;i<128;i++)providers.emplace_back(new Provider(a,log,("thread"+std::to_string(i)).c_str()));std::vector<std::thread>ts;std::array<size_t,4>counts{};for(int w=0;w<4;w++)ts.emplace_back([&,w]{phase="parallel register/query";for(int i=w;i<128;i+=4){a.ggml_backend_register(&providers[i]->reg);a.ggml_backend_register(&providers[i]->reg);req(a.ggml_backend_reg_by_name(providers[i]->id.c_str())==&providers[i]->reg,"concurrent published lookup");}counts[w]=checks;});for(auto&t:ts)t.join();req(a.ggml_backend_reg_count()==128&&a.ggml_backend_dev_count()==128,"parallel registration dedup");empty(a);size_t total=0;for(auto n:counts)total+=n;printf("PASS threads=4 concurrent_registrations=128 checks=%zu\n",total);}
int main(int argc,char**argv){if(argc<4)return 2;auto plugins=fs::absolute(argv[3]);auto events=plugins/"events.log";setenv("FG165_PLUGIN_EVENTS",events.c_str(),1);unsetenv("GGML_BACKEND_PATH");if(argc==5){API a(argv[2],true);concurrent(a);return 0;}API n(argv[1]),g(argv[2]);phase="registry";req(!dlsym(n.h,"fg165_registry_seen"),"independent native oracle");compare(registry(n),registry(g));phase="dynamic loader";compare(dynamic(n,plugins,events),dynamic(g,plugins,events));phase="best/load all";compare(best(n,plugins,events),best(g,plugins,events));bool rollback=getenv("GGML_GOOSE_REGISTRY")&&std::strcmp(getenv("GGML_GOOSE_REGISTRY"),"0")==0;req((sym<uint64_t(*)()>(g.h,"fg165_registry_seen")()!=0)!=rollback,"real Goose/rollback witness");req(sym<int64_t(*)()>(g.h,"fg165_registry_handles_live")()==0,"all explicit plugin references released");req(sym<int64_t(*)()>(g.h,"fg165_registry_heap_live")()==2||rollback,"only two persistent registry tables remain");printf("PASS registry48 plugin8 best/fallback/load_all callback_events=%zu checks=%zu rollback=%d\n",event_records,checks,rollback);}
